/* SOL 111. Each comparison follows one physical question through setup and recovery. */
(() => {
 'use strict';
 const C=window.AnalysisResponseCore;
 const table=(head,rows)=>window.LessonArticle.table(head,rows,{narrow:true});
 const {chart}=window.BeamLabs.graphics;
 const num=(n,d=3)=>n.toFixed(d);
 const trace=(low,high,count,fn)=>Array.from({length:count},(_,i)=>{
  const x=low+(high-low)*i/(count-1);
  return [x,fn(x)];
 });
 const curve=(name,pts,dash='')=>({name,pts,dash,strong:!dash});
 const plot=(options,caption)=>'<figure class="element-figure">'+chart({...options,legend:true,ph:132})+'<figcaption>'+caption+'</figcaption></figure>';
 const paragraph=text=>'<p>'+text+'</p>';
 const fields=rows=>table(['指定・参照先','この比較で確認すること'],rows);
 const check=(title,body)=>({title,body});
 const mm=vector=>1000*C.amp(vector);
 const models={
  'mfreq-one':{
   readback:["複素変位の出力でPOINT ID 13、T3を選び、表示形式が振幅・位相か実部・虚部かを確認します。", "10、38、70 Hzの同じ計算点を並べます。実部・虚部で出力した場合は二乗和の平方根を振幅とします。", "1モードと追加後の差を周波数別に見ます。差が許容範囲を超える帯域では保持数を増やします。"],
   pitfall:["モード図の先端が1だったので、実際の変位を1 mmと読んだ", "固有ベクトルの表示倍率は任意です。実際の加振力に対する変位は、SOL 111の周波数別の変位表で読みます。"],
   goals:['先端の共振ピークが合っても、10 Hzと70 Hzで差が残る理由を説明できる。'],
   points:['G13を板厚方向に押し、同じ点のT3を読む。','残す形を最初の曲げ1つに限定する。','同じ加振周波数の振幅どうしで差を測る。'],
   lesson:'細長い片持ち梁の先端を上下に揺すります。第1共振の近くでは1次の曲げが応答の大半を占めます。そこから離れると、高次の形も少しずつ先端の柔らかさに効きます。図で弱軸1モードを選び、10 Hz、38 Hz、70 Hzの順に8モードの曲線との距離を見てください。',
   input:check('保持数1と加振周波数121点を読み分ける',fields([
    ['METHOD=30 → EIGRL 30','ND=1。応答を表す形を1つ採用します。荷重方向に曲がる形か、固有ベクトルで確認します。'],
    ['FREQUENCY=60 → FREQ1 60','10～70 Hzを0.5 Hz刻みで計算するので121点です。形が1つでも周波数ごとに応答を解きます。'],
    ['DLOAD=50 → RLOAD1 50 → DAREA 51','G13の成分3へ1 N。RESVEC=NOとして基底打切りの影響を残し、参照する解でも減衰G=0.04をそろえます。']
   ])),
   result:check('G13/T3を3つの周波数で照合する',()=>{
    const fs=[10,38,70],u=(f,k)=>C.amp(C.beam(f,.04,k));
    const err=f=>100*(u(f,1)/u(f,8)-1);
    return plot({id:'modal-one-error',label:'1モードの先端振幅と8モードとの相対差',x:[10,70],y:[-5,10],xt:[10,20,30,40,50,60,70],yt:[-5,0,5,10],xl:'f (Hz)',yl:'Δ (%)',series:[curve('1 / 8',trace(10,70,121,err))],marks:fs.map(f=>[f,err(f)])},
     '独立した弱軸梁理論。縦軸は（1モードの振幅÷8モードの振幅−1）×100。0に近いほど、二つの振幅が近いことを表します。')+
     table(['周波数','弱軸1個','弱軸8個','差'],fs.map(f=>[f+' Hz',num(u(f,1))+' mm',num(u(f,8))+' mm',num(err(f),2)+'％']))+
     paragraph('変位表でG13・T3の片振幅を選び、同一周波数の行を横に比較します。38 Hzの差だけならごく小さく見えますが、70 Hzでは大小関係も変わります。10 Hzの値を静荷重によるたわみと直接比較すると、動的増幅とモード打切りの差が混ざります。');
   })
  },
  'mfreq-six':{
   readback:["固有値表と固有ベクトルで、採用した6形状のうち先端荷重方向に曲がるものを特定します。", "同じ加振周波数でG13のT3と、根元要素の同じ断面・回復点の曲げ応力を別々に並べます。", "保持数を増やして両方の変化率を計算し、評価量ごとの許容差で判断します。応力は出力要求と回復点が定義されたケースで確認します。"],
   pitfall:["掲載DATを流せば根元応力も自動で読めると思った", "掲載例は変位を要求しています。応力比較には両ケースの応力要求とPBEAMの応力回復位置もそろえます。"],
   goals:['先端変位と根元の曲げ応力について、別々にモード数の収束を判断できる。'],
   points:['変位を読む点はG13、応力を読む断面は梁の根元にそろえる。','実モデルの6モードには他方向の振動も入る。','同じ周波数、断面、表面でモード追加前後を比較する。'],
   lesson:'先端に変位計を置き、根元の表面には長手方向のひずみゲージを貼るとします。先端変位は曲がった形の高さ、根元の曲げ応力は形の曲率に対応します。高さをほとんど変えない高次の曲げが、根元の曲率を変える場合があります。操作図で残す弱軸モードを増やし、先端振幅と根元応力の変化を追ってください。',
   input:check('NDを6へ変更し、比較する出力をそろえる',fields([
    ['EIGRL 30 の ND=6','単一モードの例から変えるのは採用数。FREQUENCY、荷重、減衰、RESVECはそろえます。全方向の低い6個に、弱軸曲げが何個あるかはモード形から確認します。'],
    ['DISPLACEMENT(SORT2,PHASE)=ALL','掲載DATで要求しているのは変位です。G13・T3の振幅と位相を読みます。'],
    ['根元応力も比較する場合','両ケースでCase Controlに STRESS(PHASE)=ALL などの応力要求を追加。PBEAMの回復点、同じ要素101のA端、同じ表面の長手方向成分をそろえます。']
   ])),
   result:check('先端変位と根元応力の収束を別々に読む',()=>{
    const ns=[1,2,3,4,5,6,7,8],f=10;
    const u=n=>C.amp(C.beam(f,.04,n)),s=n=>C.amp(C.beamRootStress(f,.04,n));
    const dif=(a,n)=>100*(a(n)/a(8)-1);
    return plot({id:'modal-six-convergence',label:'弱軸モードを追加したときの変位と曲げ応力の相対差',x:[1,8],y:[-10,22],xt:[1,2,3,4,5,6,7,8],yt:[-10,0,10,20],xl:'n',yl:'Δ (%)',series:[curve('|u|',ns.map(n=>[n,dif(u,n)])),curve('|σ|',ns.map(n=>[n,dif(s,n)]),'6 4')]},
     '10 Hz、弱軸曲げ8個を基準とした理論比較。横軸を1つ進めるごとに弱軸曲げを1個追加します。8個で両曲線が0になるのは、そこを比較の基準に選んだためです。')+
     table(['弱軸曲げ','先端変位振幅','根元応力振幅'],[1,2,6,8].map(n=>[n+'個',num(u(n),4)+' mm',num(s(n),4)+' MPa']))+
     paragraph('変位が落ち着いた段階でも、根元応力の行を別に追います。実機モデルでは同じメッシュ・減衰・周波数点のまま採用範囲を広げ、評価する帯域のピークとその周波数も比較します。この表の「弱軸6個」とDATのND=6は対応が異なります。');
   })
  },
  'mfreq-antisymmetric':{
   readback:["応答が0のケースでG1/G2のT1の拘束と荷重位相を入力へ戻って照合します。", "同じ加振周波数で1次のみと2次追加後の変位を表示します。", "振幅の大小だけでなく両点の位相差を読みます。振幅が0の行に位相の物理的な意味はありません。"],
   pitfall:["G1とG2の振幅が同じなので、同じ向きに動くと判断した", "振幅は常に非負です。共通の荷重を基準に両点の位相を引き算すると、逆向きの運動を判別できます。"],
   goals:['逆位相の荷重で応答が0になるとき、拘束とモード打切りを切り分けられる。'],
   points:['同じ質量2個を同じ大きさで逆向きに押す。','対称な1次では二つの力の仕事が打ち消し合う。','逆対称な2次を足して両点の振幅と位相を比べる。'],
   lesson:'左の質点を右へ1 N、右の質点を左へ1 Nで押す瞬間を考えます。二つが同じ向きに動く1次の形では、片方の力がする仕事をもう片方が打ち消します。逆向きに動く2次の形では両方が同時に仕事をします。図で「逆位相」のまま、残すモードだけを1から2へ切り替えてください。',
   input:check('2本の荷重の位相と、残したモードを照合する',fields([
    ['DLOAD 50 → RLOAD1 511・512','両方の倍率を＋1、DAREAはG1/C1とG2/C1へ各＋1。第2荷重だけがDPHASE 541を参照し、180°遅れと同等の逆位相になります。'],
    ['G2側の符号','正の荷重に180°の位相を与えたので、係数まで−1にすると二重に反転し同位相になります。'],
    ['METHOD=30 → EIGRL 30','他の条件を固定しND=1と2で比較。SPC1の23456で両点のT1は自由。5.51 Hz付近に計算点を追加しても、基底から外したモードは復元できません。']
   ])),
   result:check('0応答の原因を2次モードの追加で検証する',()=>{
    const f=5.5,d=n=>C.two(f,.04,'pair',180,n);
    return plot({id:'modal-opposite',label:'逆位相加振で逆対称モードを追加した結果',x:[3,7],y:[-1,24],xt:[3,4,5,6,7],yt:[0,5,10,15,20],xl:'f (Hz)',yl:'|u₁| (mm)',series:[curve('n = 2',trace(3,7,161,x=>mm(C.two(x,.04,'pair',180,2).modal[0]))),curve('n = 1',[[3,0],[7,0]],'6 4')]},
     '同じ逆位相荷重でG1・T1を観測。系全体に働く力の和が0でも、形を変える2次モードには荷重が入ります。')+
     table(['5.50 Hz','G1振幅','G2振幅','両点の位相差'],[1,2].map(n=>[n+'モード',num(mm(d(n).modal[0]))+' mm',num(mm(d(n).modal[1]))+' mm',n===1?'振幅0のため未定義':'180°']))+
     paragraph('1次のみで応答が消えたら、G1/G2のT1が自由なこと、二つの荷重の位相差、採用した形の順に追います。2次を追加するとG1とG2は同振幅・逆位相になります。図と表は線形2自由度系の理論値です。');
   })
  },
  'mfreq-antiresonance':{
   readback:["同じ加振条件でG1・T1とG2・T1を出力し、どちらも同じ周波数軸に重ねます。", "両方の固有振動数に挟まれた帯域を拡大し、4.50 Hz付近のG1の谷とG2の応答を読みます。", "理論のモード別内訳と比べるときは、実部どうし、虚部どうしを先に加算し、最後に振幅を計算します。"],
   pitfall:["G1の谷底に少し振幅が残ったので、G2にも逆向きの力を追加した", "この比較ではG1だけを加振します。構造減衰があると二つの複素寄与は完全には打ち消し合いません。"],
   goals:['片側だけを加振したとき、観測点によって現れる反共振を識別できる。'],
   points:['G1に1 Nを加え、G2には荷重を加えない。','両モードを残し、同じ時刻基準で複素応答を足す。','観測点だけをG1からG2に移し、谷が残るか調べる。'],
   lesson:'左の質点だけを揺すると、ある周波数では、押している左側がほとんど動かないのに右側は動きます。左の変位を作る1次と2次の寄与が逆向きに近づくためです。両モードを残したまま図の観測点を変え、二つの山の間にある谷を比べてください。',
   input:check('荷重をG1に保ち、変位の出力だけを2点に広げる',fields([
    ['DLOAD 50 → RLOAD1 511 → DAREA 521','有効な加振はG1/C1へ1 Nの1本。G2を観測するためにG2の荷重を追加すると、別の応答を計算してしまいます。'],
    ['METHOD=30、ND=2','相殺する二つの寄与を両方採用します。1モードは谷を失う比較用の条件です。'],
    ['DISPLACEMENT → G1/T1・G2/T1','両点の複素変位を同じ周波数で出力。3.18 Hzと5.51 Hzの共振の間、特に4.50 Hz付近にも計算点を置きます。']
   ])),
   result:check('4.50 Hzで、荷重点の谷と隣の点の振幅を読む',()=>{
    const f=4.5,d=C.two(f,.04,'single',0,2);
    const series=[0,1].map(i=>curve('G'+(i+1),trace(4,5,101,x=>mm(C.two(x,.04,'single',0,2).direct[i])),i?'6 4':''));
    return plot({id:'modal-valley',label:'加振点を固定したときの二つの観測点の周波数応答',x:[4,5],y:[0,6],xt:[4,4.25,4.5,4.75,5],yt:[0,2,4,6],xl:'f (Hz)',yl:'|u| (mm)',series,marks:d.direct.map(v=>[f,mm(v)])},
     'G1のみ加振。共振間を拡大しています。実線がG1、破線がG2。減衰G=0.04のためG1の谷底にも振幅が残ります。')+
     table(['G1の内訳','実部 mm','虚部 mm'],[...d.parts.map((part,i)=>[(i+1)+'次の寄与',...part[0].map(v=>num(v*1000))]),['合成',...d.modal[0].map(v=>num(v*1000))]])+
     paragraph('合成した複素変位の大きさはG1で '+num(mm(d.modal[0]))+' mm、G2で '+num(mm(d.modal[1]))+' mmです。二つの寄与は実部で強く相殺します。振幅だけを先に足すとこの谷を失います。G1の谷を見て機器全体が静止したと判断する前に、荷重を動かさずG2を確認します。');
   })
  }
 };
 window.ModalFrequencyCases=models;
})();
